          right: { label: "Pleonasmo vicioso × literário", text: "**Vicioso (vício de linguagem):** redundância inútil que não reforça nada — 'subir para cima', 'entrar para dentro', 'sair para fora'. **Literário (estilístico):** redundância INTENCIONAL, com efeito expressivo — 'Vi com meus próprios olhos', 'E ria, ria, ria'." },
